'// Class representing a Car
class Car {
    private String brand;
    private String model;

    // Constructor
    public Car(String brand, String model) {
        this.brand = brand;
        this.model = model;
    }

    // Method to get the brand of the car
    public String getBrand() {
        return brand;
    }

    // Method to get the model of the car
    public String getModel() {
        return model;
    }
}

// Class representing a Garage
class Garage {
    private Car[] cars;
    private int capacity;
    private int count;

    // Constructor
    public Garage(int capacity) {
        this.capacity = capacity;
        this.cars = new Car[capacity];
        this.count = 0;
    }

    // Method to add a car to the garage
    public void addCar(Car car) {
        if (count < capacity) {
            cars[count++] = car;
            System.out.println(car.getBrand() + " " + car.getModel() + " added to the garage.");
        } else {
            System.out.println("Garage is full. Cannot add more cars.");
        }
    }

    // Method to list all cars in the garage
    public void listCars() {
        System.out.println("Cars in the garage:");
        for (int i = 0; i < count; i++) {
            System.out.println(cars[i].getBrand() + " " + cars[i].getModel());
        }
    }
}

// Main class to demonstrate the usage of Car and Garage classes
public class Main {
    public static void main(String[] args) {
        // Create some car objects
        Car car1 = new Car("Toyota", "Corolla");
        Car car2 = new Car("Honda", "Civic");
        Car car3 = new Car("Ford", "Mustang");

        // Create a garage object
        Garage garage = new Garage(2);

        // Add cars to the garage
        garage.addCar(car1);
        garage.addCar(car2);
        garage.addCar(car3); // Trying to add more cars than the garage capacity

        // List cars in the garage
        garage.listCars();
    }
}
'

